-- UofT Engineering, new this year: question 3 takes question 2's analytical
-- problem, changes one condition, and asks how the student would re-evaluate it
-- and whether the solution (the 3 factors) changes.
-- A bank question's follow-ups can now be asked as questions of their own.
alter table public.mock_interview_bank_questions add column if not exists follow_up_linked boolean not null default false;
alter table public.mock_interview_bank_questions add column if not exists follow_up_prep integer;
alter table public.mock_interview_bank_questions add column if not exists follow_up_response integer;
comment on column public.mock_interview_bank_questions.follow_up_prep is 'Seconds to prepare a linked follow-up; null = same as the main question.';
comment on column public.mock_interview_bank_questions.follow_up_response is 'Seconds to answer a linked follow-up; null = same as the main question.';
comment on column public.mock_interview_bank_questions.follow_up_linked is 'Follow-ups are asked as their own numbered, timed questions (e.g. UofT Engineering Q3 builds on Q2).';

-- Practice pool: 40 analytical questions, each with its changed-condition question.
values ('7c1d2e3f-4a5b-4c6d-8e9f-0a1b2c3d4e5f', 'pool', '多大工程 · 分析题 + 条件变化（第二、三题联动）',
  '多伦多大学工程视频面试新题型（练习题，非真题）：第二题是分析/估算题，第三题在第二题基础上改变一个条件，问你如何重新评估、方案（3 个变量）是否需要调整。答题思路：先说哪个变量受影响、怎样影响 → 是否要新增或替换变量 → 结论是否改变。',
  true, true, 60, 180)
on conflict (id) do nothing;


